#if UNITY_EDITOR
using System;using System.Linq;using System.Reflection;using System.Collections.Generic;using NUnit.Framework;using UnityEngine;using SporeGobbo.Geometry;using SporeGobbo.CampCandidate;
/// <summary>Owned detached occupancy and real-owner policy contracts; no Camp bootstrap, campaign, scenes, files or preferences.</summary>
public sealed class Stage64BLabTests
{
 readonly List<GameObject> owned=new List<GameObject>();CampFightPitLab lab;GobboController player;BuddyUnit a,b;
 const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 GameObject Make(string name){var go=new GameObject(name);owned.Add(go);go.AddComponent<Rigidbody2D>();return go;}
 void Field(string name,object value)=>typeof(CampFightPitLab).GetField(name,Hidden).SetValue(lab,value);
 void Phase(CampFightPitLab.MatchPhase value)=>Field("<Phase>k__BackingField",value);
 Dictionary<GameObject,int> Teams=>(Dictionary<GameObject,int>)typeof(CampFightPitLab).GetField("teams",Hidden).GetValue(lab);
 List<GameObject> Fighters=>(List<GameObject>)typeof(CampFightPitLab).GetField("fighters",Hidden).GetValue(lab);
 BuddyUnit Buddy(string name){var unit=Make(name).AddComponent<BuddyUnit>();unit.Initialize(new GobboUnitSaveData{uniqueId=name,health=20,maxHealth=20});return unit;}
 void Bind(GameObject actor,int team){Teams.Add(actor,team);var binding=actor.AddComponent<CombatSessionBinding>();binding.Rules=lab;binding.Team=team;}
 [SetUp]public void Setup(){lab=Make("owned inactive policy adapter, no lifecycle bootstrap").AddComponent<CampFightPitLab>();player=Make("owned actual player").AddComponent<GobboController>();player.health=20;Field("player",player);a=Buddy("owned-a");b=Buddy("owned-b");Bind(a.gameObject,0);Bind(b.gameObject,1);Bind(player.gameObject,-1);Fighters.Add(a.gameObject);Fighters.Add(b.gameObject);Phase(CampFightPitLab.MatchPhase.Fighting);}
 [TearDown]public void Cleanup(){if(lab!=null)Phase(CampFightPitLab.MatchPhase.Idle);foreach(var go in owned)if(go!=null)foreach(var binding in go.GetComponents<CombatSessionBinding>())binding.Rules=null;for(int i=owned.Count-1;i>=0;i--)if(owned[i]!=null)UnityEngine.Object.DestroyImmediate(owned[i]);owned.Clear();}
 [Test]public void RealBuddyDamageStopsAtOneBeforeDeathAndRejectsQueuedHit(){var result=EnemyDamage.TryApply(b.gameObject,new EnemyDamageRequest(1000,"owned-a",a.gameObject));Assert.That(result.Accepted,Is.True);Assert.That(result.AppliedDamage,Is.EqualTo(19));Assert.That(b.unitData.health,Is.EqualTo(1));Assert.That(b.unitData.isDead,Is.False);Assert.That(lab.Phase,Is.EqualTo(CampFightPitLab.MatchPhase.Resolved));Assert.That(lab.AcceptedHits,Is.EqualTo(1));Assert.That(EnemyDamage.TryApply(a.gameObject,new EnemyDamageRequest(1000,"owned-b",b.gameObject)).Accepted,Is.False);Assert.That(a.unitData.health,Is.EqualTo(20));}
 [Test]public void SpectatorAndUnselectedGobboAreNotEligibleTargets(){Assert.That(EnemyDamage.Eligible(a.gameObject,player),Is.False);var stranger=Buddy("owned-stranger");Assert.That(EnemyDamage.Eligible(a.gameObject,stranger),Is.False);Assert.That(stranger.unitData.health,Is.EqualTo(20));}
 [Test]public void ZeroRemainingAllowanceResolvesRatherThanStalling(){b.unitData.health=1;Assert.That(lab.LimitDamage(b.gameObject,new EnemyDamageRequest(2,"",a.gameObject),2),Is.Zero);Assert.That(lab.Phase,Is.EqualTo(CampFightPitLab.MatchPhase.Resolved));}
 [Test]public void ActualLeaderGodModeRejectsLossWithoutSecondHealthStore(){Teams[player.gameObject]=0;player.defense=0;lab.GodMode=true;Assert.That(player.ReceiveCombatDamage(new EnemyDamageRequest(8,"owned-b",b.gameObject)).Accepted,Is.False);Assert.That(player.health,Is.EqualTo(20));lab.GodMode=false;Assert.That(player.ReceiveCombatDamage(new EnemyDamageRequest(8,"owned-b",b.gameObject)).AppliedDamage,Is.EqualTo(8));Assert.That(player.health,Is.EqualTo(12));}
 [Test]public void UnsafePoisonAndDirectFoodXpAreSuppressedInSession(){a.ApplyPoison(5,3,1);player.TakePoison(5,3,1);Assert.That(a.IsPoisoned,Is.False);Assert.That(player.isPoisoned,Is.False);int xp=player.xp;player.AddXP(30);Assert.That(player.xp,Is.EqualTo(xp));}
 [Test]public void ProjectileRetainsImmutableSessionOwnershipAfterSourceDestroyed(){var host=Make("owned projectile");host.AddComponent<CircleCollider2D>();var shot=host.AddComponent<EnemyProjectile>();shot.Launch(Vector2.right,a.transform);UnityEngine.Object.DestroyImmediate(a.gameObject);Assert.That(shot.SessionRules,Is.SameAs(lab));}
 Transform DashTarget(Collider2D hit)=>(Transform)typeof(GobboController).GetMethod("ResolveLivingEnemy",Hidden).Invoke(player,new object[]{hit});
 [Test]public void DashTargetUsesCanonicalSessionEligibilityWithoutGrantingAbility(){Teams[player.gameObject]=0;var child=Make("owned child hurtbox");child.transform.SetParent(b.transform);var hurt=child.AddComponent<CircleCollider2D>();Assert.That(DashTarget(hurt),Is.SameAs(b.transform));var ally=a.gameObject.AddComponent<CircleCollider2D>();Assert.That(DashTarget(ally),Is.Null);Teams[b.gameObject]=-1;Assert.That(DashTarget(hurt),Is.Null);Teams[b.gameObject]=1;Phase(CampFightPitLab.MatchPhase.Resolved);Assert.That(DashTarget(hurt),Is.Null);}
 [Test]public void DashTargetRejectsOrdinaryAlliesDeadDisabledAndUnready(){Teams[player.gameObject]=0;var hurt=b.gameObject.AddComponent<CircleCollider2D>();b.unitData.health=0;Assert.That(DashTarget(hurt),Is.Null);b.unitData.health=20;b.enabled=false;Assert.That(DashTarget(hurt),Is.Null);b.enabled=true;b.gameObject.AddComponent<ActorTerrainBinding>();Assert.That(DashTarget(hurt),Is.Null);a.gameObject.GetComponent<CombatSessionBinding>().Rules=null;player.GetComponent<CombatSessionBinding>().Rules=null;Assert.That(DashTarget(a.gameObject.AddComponent<CircleCollider2D>()),Is.Null);}
 [Test]public void TemporaryPlayerMotionRestorationPreservesPriorSuppressionAndCooldown(){typeof(GobboController).GetField("dashCooldownTimer",Hidden).SetValue(player,2f);var restore=player.CaptureTemporaryCombatRestoration();player.SuppressTemporaryInput=true;typeof(GobboController).GetField("dashCooldownTimer",Hidden).SetValue(player,9f);restore();Assert.That(player.SuppressTemporaryInput,Is.False);Assert.That((float)typeof(GobboController).GetField("dashCooldownTimer",Hidden).GetValue(player),Is.EqualTo(2));}
 [TestCase("Rock")][TestCase("Roots")][TestCase("Dirt")]public void TemporaryFilledOpenFloorNeverBecomesPersistentExcavation(string preset){var definition=SettlementCampLayout.Shared;var state=new RegionTerrainState("owned-preset-contract",192,192,definition);var cut=state.TakeMutationControl();var place=state.TakePlacementControl();var cells=new[]{new DualTile(151,79),new DualTile(152,79)};Assert.That(cells.All(c=>!state.World.BaseSolid(c.X,c.Y)),Is.True);var result=place(new TerrainPlacementRequest(state.InstanceId,state.Revision,"owned-"+preset,cells),c=>true);Assert.That(result.Accepted,Is.True);Assert.Throws<InvalidOperationException>(()=>state.ExportDeltas());int publication=state.Revision;Assert.That(cut(cells,state.Revision,c=>true),Is.EqualTo(2));Assert.That(state.Revision,Is.GreaterThan(publication));Assert.That(state.ExportDeltas(),Is.Empty);Assert.That(state.World.EditCount,Is.Zero);}
 [Test]public void ArenaPlacementRejectsOutsideProtectedAndStaleBatchAtomically(){var state=new RegionTerrainState("owned-placement-contract",192,192,SettlementCampLayout.Shared);state.TakeMutationControl();var place=state.TakePlacementControl();var inside=new DualTile(151,79);foreach(var outside in new[]{new DualTile(84,116),new DualTile(0,0)}){var r=place(new TerrainPlacementRequest(state.InstanceId,0,"owned-"+outside.X,new[]{inside,outside}),c=>true);Assert.That(r.Accepted,Is.False);Assert.That(state.World.IsSolid(inside.X,inside.Y),Is.False);Assert.That(state.Revision,Is.Zero);}Assert.That(place(new TerrainPlacementRequest(state.InstanceId,1,"owned-stale",new[]{inside}),c=>true).Accepted,Is.False);}
 [Test]public void CameraCentreIsNotAutomaticallyAValidRockPresetRally()
 {var state=new RegionTerrainState("owned-rally-clearance",192,192,SettlementCampLayout.Shared);state.TakeMutationControl();var place=state.TakePlacementControl();var rock=new List<DualTile>();for(int y=78;y<=81;y++)for(int x=148;x<=150;x++)rock.Add(new DualTile(x,y));Assert.That(place(new TerrainPlacementRequest(state.InstanceId,0,"owned-rock",rock),c=>true).Accepted,Is.True);Assert.That(state.Route(new Point2(143.5,79.5),CampFightPitLayout.Center,3),Is.Empty);Assert.That(state.Route(new Point2(143.5,79.5),new Point2(152.5,82.5),3).Count,Is.GreaterThan(0));}
 [Test]public void ArenaFillClearPreservesUnrelatedOrdinaryExcavation(){var d=SettlementCampLayout.Shared;var state=new RegionTerrainState("owned-mixed",192,192,d);var cut=state.TakeMutationControl();var place=state.TakePlacementControl();var ordinary=new DualTile(70,110);if(d.Category(ordinary.X,ordinary.Y)!=CampCell.Expansion)ordinary=Enumerable.Range(0,192*192).Where(i=>d.Category(i%192,i/192)==CampCell.Expansion).Select(i=>new DualTile(i%192,i/192)).First();cut(new[]{ordinary},0,c=>true);int[] before=state.ExportDeltas();for(int i=0;i<20;i++){var cells=new[]{new DualTile(151,79)};Assert.That(place(new TerrainPlacementRequest(state.InstanceId,state.Revision,"owned-cycle-"+i,cells),c=>true).Accepted,Is.True);cut(cells,state.Revision,c=>true);Assert.That(state.ExportDeltas(),Is.EqualTo(before));}Assert.That(state.World.IsSolid(ordinary.X,ordinary.Y),Is.False);}
}
#endif
